    def _eval_eye(cls, rows, cols):
        def entry(i, j):
            return S.One if i == j else S.Zero
        return cls._new(rows, cols, entry)
    @classmethod
    def _eval_jordan_block(cls, rows, cols, eigenvalue, band='upper'):
        if band == 'lower':
            def entry(i, j):
                if i == j:
                    return eigenvalue
                elif j + 1 == i:
                    return S.One
                return S.Zero
        else:
